with participants as (select c.player1_id as player_id from public.matches m join public.couples c on c.id in (m.couple1_id,m.couple2_id) where m.tournament_id='29feadb9-a0b3-4589-a4cb-9e66c288f00b' union select c.player2_id from public.matches m join public.couples c on c.id in (m.couple1_id,m.couple2_id) where m.tournament_id='29feadb9-a0b3-4589-a4cb-9e66c288f00b') select 'players_in_recorded_matches' as check_name, count(*)::text as value from participants union all select 'saved_history', count(*)::text from public.player_tournament_history where tournament_id='29feadb9-a0b3-4589-a4cb-9e66c288f00b' union all select 'frozen_substitutions',count(*)::text from long_substitution_private.match_lineups l join public.matches m on m.id=l.match_id where m.tournament_id='29feadb9-a0b3-4589-a4cb-9e66c288f00b' and l.substitute_slot is not null union all select 'disqualifications',count(*)::text from public.tournament_couple_disqualifications where tournament_id='29feadb9-a0b3-4589-a4cb-9e66c288f00b' and status='ACTIVE' union all select 'test_tournament',es_prueba::text from public.tournaments where id='29feadb9-a0b3-4589-a4cb-9e66c288f00b';